41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const premiumFor = (quote: QuoteStep): number => {
54	  const policyBase = quote.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
55	  return Math.ceil(policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
56	};
57	
58	const resultOf = (step: Step): StepResult => {
59	  if (step.op === "quote") return { premium: premiumFor(step) };
60	  throw new Error(`unsupported step: ${step.op}`);
61	};
62	
63	export const runScenario = (scenario: Scenario): ScenarioResult => ({
64	  results: scenario.steps.map(resultOf),
65	});
