const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type KnownItemType = keyof typeof BASE_PREMIUMS;

const basePremiumOf = (itemType: string): number => BASE_PREMIUMS[itemType as KnownItemType];
